//! ESP-IDF's C types, constants and function declarations, generated by bindgen from the
//! headers the firmware compiles against; see `build.rs`.

#![no_std]
#![expect(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    reason = "the names are ESP-IDF's"
)]
#![expect(
    clippy::manual_div_ceil,
    clippy::missing_safety_doc,
    clippy::ptr_offset_with_cast,
    clippy::useless_transmute,
    reason = "bindgen's output"
)]
#![cfg_attr(
    esp32p4,
    expect(
        clippy::too_many_arguments,
        unsafe_op_in_unsafe_fn,
        reason = "bindgen's output"
    )
)]

/// The C pointers that `&Self` and `&mut Self` stand for in an `#[export]`.
pub trait CPointer {
    type Shared;
    type Unique;
}

/// bindgen's types and C's scalars are `Copy`; the kernel's handle types aren't and say what C sees.
impl<T: Copy> CPointer for T {
    type Shared = *const T;
    type Unique = *mut T;
}

/// Makes `&$kernel` in an `#[export]` the C handle `$c`, which C shares between tasks. With
/// `owned`, `&mut` and `Box` stand for it too: C passes it back for the kernel to free or step.
#[macro_export]
macro_rules! c_handle {
    (@ $kernel:ty, $shared:ty, $unique:ty) => {
        impl $crate::CPointer for $kernel
        where
            Self: Sync,
        {
            type Shared = $shared;
            type Unique = $unique;
        }
    };
    ($kernel:ty, $c:ty) => {
        $crate::c_handle!(@ $kernel, $c, ());
    };
    ($kernel:ty, $c:ty, owned) => {
        $crate::c_handle!(@ $kernel, $c, $c);
    };
}

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
